const { AndroidConfig, withAndroidStyles } = require('expo/config-plugins');

// Must match the resource generated by the expo-font plugin for the
// `PlusJakartaSans` Android font family: it writes
// `res/font/xml_plus_jakarta_sans.xml` (prefix `xml_` + the family name
// converted to a valid Android resource name).
const FONT_RESOURCE = '@font/xml_plus_jakarta_sans';

/**
 * Sets Plus Jakarta Sans as the Android platform default typeface on AppTheme,
 * so native / third-party text that does not pass through the app's Text
 * wrapper still ignores a device-forced system font. Best-effort safety net;
 * the JS `Text` wrapper remains the guarantee for the app's own text.
 */
const withAndroidDefaultFont = (config) => {
  return withAndroidStyles(config, (config) => {
    config.modResults = AndroidConfig.Styles.assignStylesValue(
      config.modResults,
      {
        add: true,
        parent: AndroidConfig.Styles.getAppThemeGroup(),
        name: 'android:fontFamily',
        value: FONT_RESOURCE,
      },
    );
    return config;
  });
};

module.exports = withAndroidDefaultFont;
